@staticmethod
def _extract_json(raw: str) -> dict[str, Any]:
    """Parse one model action, tolerating literal control chars inside JSON strings.

    Some local models emit multiline source code in ``write_file.args.content``
    with literal newlines instead of JSON ``\n`` escapes. Python's strict JSON
    parser rejects that otherwise structurally valid action. We first keep
    strict parsing, then retry only with ``strict=False``; no structural
    repair or guessing is performed.
    """
    raw = raw.strip()
    if raw.startswith("```"):
        raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw, flags=re.I | re.S).strip()

    def load_object(candidate: str) -> dict[str, Any] | None:
        for strict in (True, False):
            try:
                obj = json.loads(candidate, strict=strict)
            except json.JSONDecodeError:
                continue
            if isinstance(obj, dict):
                return obj
        return None

    obj = load_object(raw)
    if obj is not None:
        return obj
    start = raw.find("{")
    end = raw.rfind("}")
    if start >= 0 and end > start:
        obj = load_object(raw[start : end + 1])
        if obj is not None:
            return obj
    raise AgentError("Modellantwort enthält kein gültiges JSON-Objekt.")

