@staticmethod
def _extract_json(raw: str) -> dict[str, Any]:
    """Parse one complete JSON object from otherwise noisy model output.

    Local models sometimes emit literal newlines inside JSON strings and may
    append prose, markdown fences or an extra closing brace after an otherwise
    complete action. Keep strict/lenient JSON parsing, then scan balanced
    objects while respecting quoted strings and escapes. No semantic repair or
    guessing is performed.
    """
    raw = raw.strip()
    if raw.startswith("```"):
        raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw, flags=re.I | re.S).strip()

    def load_object(candidate: str) -> dict[str, Any] | None:
        for strict in (True, False):
            try:
                obj = json.loads(candidate, strict=strict)
            except json.JSONDecodeError:
                continue
            if isinstance(obj, dict):
                return obj
        return None

    obj = load_object(raw)
    if obj is not None:
        return obj

    depth = 0
    start: int | None = None
    in_string = False
    escaped = False

    for idx, char in enumerate(raw):
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            continue

        if char == '"':
            in_string = True
            continue
        if char == "{":
            if depth == 0:
                start = idx
            depth += 1
            continue
        if char == "}" and depth:
            depth -= 1
            if depth == 0 and start is not None:
                obj = load_object(raw[start : idx + 1])
                if obj is not None:
                    return obj
                start = None

    raise AgentError("Modellantwort enthält kein gültiges JSON-Objekt.")
